// @ts-check

// This runs in Node.js - Don't use client-side code here (browser APIs, JSX...)

const fs = require('fs');
const path = require('path');

/**
 * 侧边栏布局（薄层）：
 * 顶层只声明栏目顺序与「编程」聚合栏；栏目显示名/折叠状态
 * 全部由各目录下的 _category_.json 就近提供（单一事实源在内容侧）。
 *
 * 注意：Docusaurus 的 autogenerated 只展开 dirName 目录的「内容」，
 * 不会把该目录本身变成一个分类。所以每个栏目必须用 category 包一层，
 * 否则栏目内所有文档会被平铺到同一层级，导航层级整条塌掉。
 *
 * 新增栏目：建目录 + 放 _category_.json + 在下方 column() 列表加一行。
 * 新增编程子栏目：同样建目录 + _category_.json，并登记进 CODE_COLUMNS。
 */

const DOCS_DIR = path.join(__dirname, 'docs');

/** 读取栏目目录的 _category_.json（缺失或损坏时以目录名兜底） */
function readCategoryMeta(dirName) {
  try {
    return JSON.parse(
      fs.readFileSync(path.join(DOCS_DIR, dirName, '_category_.json'), 'utf8'),
    );
  } catch {
    return {};
  }
}

/** 把栏目目录包成分类，显示元数据取自该目录的 _category_.json */
function column(dirName) {
  const {label = dirName, collapsible = true, collapsed} = readCategoryMeta(dirName);
  return {
    type: 'category',
    label,
    collapsible,
    ...(collapsed === undefined ? {} : {collapsed}),
    items: [{type: 'autogenerated', dirName}],
  };
}

/** 「编程」聚合栏下的子栏目（数组顺序即显示顺序） */
const CODE_COLUMNS = ['react', 'rust', 'python', 'java', 'docusaurus'];

/** 顶层独立栏目（数组顺序即显示顺序） */
const KNOWLEDGE_COLUMNS = ['patterns', 'math', 'physics', 'education', 'poetry'];

/** @type {import('@docusaurus/plugin-content-docs').SidebarsConfig} */
const sidebars = {
  nodeSidebar: [
    column('intro'),
    {
      type: 'category',
      label: '编程',
      collapsed: false,
      items: CODE_COLUMNS.map((dirName) => column(dirName)),
    },
    ...KNOWLEDGE_COLUMNS.map((dirName) => column(dirName)),
  ],
};

module.exports = sidebars;
